## Create a DataFrame from the pasted code list map
list_in = phecode_icd10_map_text.splitlines()
codelist = []
for line in list_in:
    # list of tuples
    codelist.append(tuple(line.split("\t")))
header = ["ICD10", "PheCode", "PheCode_parent", "Phenotype", "Phenotype_parent", "Category", "Sex"]
phe_icd10_codelist = spark.createDataFrame(codelist, header)
display(phe_icd10_codelist)

## Save the code list
db_collab = ""
phe_icd10_codelist_name = "ccu022_01_PheCode_ICD10_AllPheCodes_map"
phe_icd10_codelist.write.option("overwriteSchema", "true").saveAsTable(name=(db_collab + '.' + phe_icd10_codelist_name + file_date), mode="overwrite")

# COMMAND ----------

phe_icd10_codelist.count()